changeSet.neo4j:cypher:
CREATE INDEX term_origin_name_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name);

CREATE INDEX term_cde_lookup_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name, t.origin_id, t.handle, t.origin_version);

CREATE INDEX term_crdc_lookup_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name, t.origin_id);

CREATE INDEX vs_nanoid_idx IF NOT EXISTS
FOR (vs:value_set)
ON (vs.nanoid);

CREATE INDEX vs_handle_idx IF NOT EXISTS
FOR (vs:value_set)
ON (vs.handle);

CALL { // Cypher Migration File // Generated: 2026-03-30 18:03:40.816444
// ---------- CREATE VALUESET and ATTACH OBIB TERMS ---------- MERGE (vs:value_set {nanoid: "Pmz0m6"}) ON CREATE SET vs._commit = "test-OBIB-20260330", vs.handle = "obib_terms_valueset"
WITH vs
MATCH (t:term {origin_name:"OBIB"}) MERGE (vs)-[:has_term]->(t)
WITH vs
// ---------- CREATE CRDC TERM ---------- MERGE (ref:term { origin_name: "CRDC", origin_id: "CRDC0002" }) ON CREATE SET ref._commit = "CDEPV-20260421" ON CREATE SET ref.nanoid = "F781bv" ON CREATE SET ref.origin_version = "1" ON CREATE SET ref.value = "obib value set reference" ON CREATE SET ref.handle = "obib_valueset_reference"
WITH vs, ref
// ---------- CREATE TAGS ---------- MERGE (tag1:tag {key: "provenance", value: "CTOS experts"}) ON CREATE SET tag1._commit = "test-OBIB-20260330"
MERGE (tag2:tag {key: "added", value: "04-21-2026"}) ON CREATE SET tag2._commit = "test-OBIB-20260330"
MERGE (ref)-[:has_tag]->(tag1) MERGE (ref)-[:has_tag]->(tag2)
WITH vs, ref
// ---------- LINK CRDC TERM TO VALUESET ---------- MERGE (ref)-[:specifies_value_set]->(vs)
WITH vs
// ---------- CDE MAPPING ---------- MATCH (cde:term { handle: "specimen_material_obib_source", origin_id: "11253427", origin_name: "caDSR", origin_version: "1.00" })
WITH cde, vs MERGE (cde)-[:specifies_value_set]->(vs) }
